property baud_freq_influence;
    logic [11:0] captured_baud_freq;
    @(posedge clock)
    ($rose(ce_16), captured_baud_freq = baud_freq) |-> ##(16 * captured_baud_freq) $rose(ce_16);
endproperty

assert property (baud_freq_influence);
```
